CREATE TABLE public."liabilities" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME public."liabilities_id_seq" START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE) NOT NULL,
  "account_id" bigint NOT NULL,
  "liability_type" text NOT NULL,
  "principal_original" numeric(14,2),
  "principal_current" numeric(14,2),
  "annual_rate" numeric(7,4),
  "minimum_payment" numeric(14,2),
  "payment_day" smallint,
  "term_end_date" date,
  "interest_free_until" date,
  "target_close_date" date,
  "target_extra_payment" numeric(14,2) DEFAULT 0,
  "priority" smallint,
  "notes" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "balance_model" text NOT NULL,
  "linked_account_id" bigint,
  "payment_account_id" bigint,
  "status" text DEFAULT 'active'::text NOT NULL,
  "name" text NOT NULL,
  "minimum_payment_calculation_day" smallint
);
